head.script:
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. Source 탭 또는 Property 탭에서 gridView1 의 헤더인 column7 과 컬럼인 col1 의 inputType 부분을 확인한다.
    //1. In the Source tab or the Property tab, check the column header of gridView1 and the inputType part of the col1 column.
    //Verify step 1. inputType="checkbox"
    //1. inputType = "checkbox"
    //Test step 2. gridView2 의 헤더인 column7 과 컬럼인 col1 의 inputType 부분을 확인한다.
    //2. Check the header of the gridView2, column7, and the inputType part of the col1 column.
    //Verify step 2. inputType="checkbox"
    //2. inputType = "checkbox"
    //Test step 3. Script 탭에서 gridView1.setCellChecked 부분을 확인한다.
    //3. In the Script tab, check gridView1.setCellChecked.
    //Verify step 3. 코멘트확인
    //3. Confirm comments
    //Test step 4. datalist2 의 use 부분을 확인한다.
    //4. Check the use part of datalist2.
    //Verify step 4. 코멘트확인
    //4. Confirm comments
    //Test step 5. 브라우저에서 헤더의 체크박스 부분을 확인한다.
    //5. In the browser, check the checkbox section of the header.
    WebSquare.wUnit.addCommand("pause", "1000");
    //Verify step 5. 그리드1, 그리드2 - 표시로 되어있다. (그전버전에서는 그리드1 에 헤더체크박스가 다르게 표시됨)
    //5. Grid 1, Grid 2 - Indicates the display. (Previously, Grid 1 displayed different header checkboxes.)
    WebSquare.wUnit.addCommand("pause", "500");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_column7').childNodes[0].indeterminate", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView2_column7').childNodes[0].indeterminate", "true");
    WebSquare.wUnit.addCommand("pause", "1000");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    gridView1.setCellChecked(0, "col1", false);
    //dataList1.setCellData( 0 , "col1" , "0" );
    //Function 
    //Created by: Quan.Nguyen
    //Created date: 30-Jan-2018
    //end
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
